namespace Atlas\Platform\PatientResources\Repositories;
use Atlas\Platform\Core\Audit\AuditRecorder;use Atlas\Platform\PatientResources\Domain\PatientResourceVariant;use RuntimeException;
final class WordPressVariantRepository implements VariantRepository{private string$table;public function __construct(private object$db,private AuditRecorder$audit){$this->table=$db->prefix.'atlas_patient_resource_variants';}public function save(string$org,string$version,array$custom,string$key,int$actor,string$name=''):PatientResourceVariant{$existing=$this->byKey($key);if($existing!==null){if($existing->organizationId!==$org||$existing->resourceVersionId!==$version){throw new RuntimeException('Idempotency key conflict.');}return$existing->replayed();}$id=wp_generate_uuid4();$created=gmdate('Y-m-d H:i:s');$json=wp_json_encode($custom);if(!is_string($json)){throw new RuntimeException('Unable to encode patient resource customizations.');}if($this->db->query('START TRANSACTION')===false){throw new RuntimeException('Unable to start the patient resource transaction.');}try{if($this->db->insert($this->table,['id'=>$id,'organization_id'=>$org,'resource_version_id'=>$version,'name'=>$name,'customizations_json'=>$json,'status'=>'active','idempotency_key'=>$key,'created_by'=>$actor,'created_at'=>$created,'updated_at'=>$created],['%s','%s','%s','%s','%s','%s','%s','%d','%s','%s'])===false){throw new RuntimeException('Unable to save patient resource variant.');}$this->audit->record('patient_resource.variant_created','patient_resources',$actor,$org,'patient_resource_variant',$id,['resource_version_id'=>$version]);if($this->db->query('COMMIT')===false){throw new RuntimeException('Unable to commit patient resource variant.');}}catch(\Throwable$failure){$this->db->query('ROLLBACK');$existing=$this->byKey($key);if($existing!==null&&$existing->organizationId===$org&&$existing->resourceVersionId===$version){return$existing->replayed();}throw$failure;}return new PatientResourceVariant($id,$org,$version,$custom,$created,false,$name,'active',$created);}public function findForOrganization(string$id,string$org):?PatientResourceVariant{$r=$this->db->get_row($this->db->prepare("SELECT * FROM `{$this->table}` WHERE id=%s AND organization_id=%s LIMIT 1",$id,$org),ARRAY_A);return$this->map($r);}public function listForOrganization(string$org,int$limit=25):array{$limit=max(1,min(100,$limit));$rows=$this->db->get_results($this->db->prepare("SELECT * FROM `{$this->table}` WHERE organization_id=%s ORDER BY created_at DESC LIMIT %d",$org,$limit),ARRAY_A);if(!is_array($rows)){return[];}return array_values(array_filter(array_map(fn($row)=>$this->map($row),$rows)));}public function updateCustomizations(string$id,string$org,array$custom,int$actor,string$name=''):bool{$json=wp_json_encode($custom);if(!is_string($json)){return false;}$updated=gmdate('Y-m-d H:i:s');$ok=$this->db->update($this->table,['customizations_json'=>$json,'name'=>$name,'status'=>'active','updated_at'=>$updated],['id'=>$id,'organization_id'=>$org],['%s','%s','%s','%s'],['%s','%s'])!==false;if($ok){$this->audit->record('patient_resource.variant_updated','patient_resources',$actor,$org,'patient_resource_variant',$id,[]);}return$ok;}public function setStatus(string$id,string$org,string$status,int$actor):bool{if(!in_array($status,['active','archived'],true)){return false;}$ok=$this->db->update($this->table,['status'=>$status,'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$id,'organization_id'=>$org],['%s','%s'],['%s','%s'])!==false;if($ok){$this->audit->record('patient_resource.variant_'.$status,'patient_resources',$actor,$org,'patient_resource_variant',$id,[]);}return$ok;}private function byKey(string$key):?PatientResourceVariant{$r=$this->db->get_row($this->db->prepare("SELECT * FROM `{$this->table}` WHERE idempotency_key=%s LIMIT 1",$key),ARRAY_A);return$this->map($r);}private function map(mixed$r):?PatientResourceVariant{if(!is_array($r)){return null;}$data=json_decode((string)$r['customizations_json'],true);return is_array($data)?new PatientResourceVariant((string)$r['id'],(string)$r['organization_id'],(string)$r['resource_version_id'],array_map('strval',$data),(string)$r['created_at'],false,(string)($r['name']??''),(string)($r['status']??'active'),isset($r['updated_at'])&&(string)$r['updated_at']!==''?(string)$r['updated_at']:null):null;}}
